experiments.source:
header {gq=1,assembly="GRCh38"}
let U=g[1:198600000..198800000]
let R=g[1:198696711..198696909:-]
let J=j[1:198692373..198703297:-]
from @x.records |> within U |> derive {a=any unique {overlaps(R,min:12bp)},b=any unique {J},joint=any unique {overlaps(R,min:12bp) & J}} |> tally {a,b,joint} by {sample}

header {gq=1,assembly="GRCh38"}
